let palette = ['#116B90', '#CA2126', '#F9C11F', '#F38842', '#F2F3F3'];
let circles = [];
let zoomEffect;
let bgColor;
let sceneFrame = 0;
let nextBgColor;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	bgColor = '#2F3351';
	addCircles();
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

	sceneFrame++;
	push();
	if (sceneFrame > 250) {
		zoomEffect.run();
	}

	translate(width / 2, height / 2);
	scale(0.8);
	translate(-width / 2, -height / 2);

	background(bgColor);
	for (let circleMotion of circles) {
		circleMotion.run();
	}

	if (sceneFrame === 250) {
		zoomEffect = new Zoom();
	}

	if (sceneFrame === 290) {

		let previousBgColor = bgColor;
		bgColor = nextBgColor;
		palette.push(previousBgColor);

		let nextBgColorIndex = palette.indexOf(nextBgColor);
		if (nextBgColorIndex !== -1) {
			palette.splice(nextBgColorIndex, 1);
		}

		circles = [];
		zoomEffect = null;
		sceneFrame = 0;
		addCircles();
	}

	pop();

  pop();
}

function easeInOutQuad(x) {
	return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
}

function addCircles() {
	let tileCount = 5;
	let tileSize = width / tileCount;
	let circleCount = 0;
	for (let i = 0; i < tileCount; i++) {
		for (let j = 0; j < tileCount; j++) {
			let x = i * tileSize + (tileSize / 2);
			let y = j * tileSize + (tileSize / 2);
			let w = tileSize * 0.5;
			let sw = width * 0.005;
			let circleColor = random(palette);
			let startFrameOffset = -(i + j) * 10;
			circles.push(new CircleMotion(x, y, w, sw, circleColor, startFrameOffset));
			circleCount++;
			if (circleCount === 13) {
				nextBgColor = circleColor;
			}
		}
	}
}

/*------------------------------------------------------------------------------------------*/

class CircleMotion {
	constructor(x, y, diameter, thickness, fillColor, startFrame) {
		this.x = x;
		this.y = y;
		this.diameter = diameter;
		this.strokeThickness = thickness;
		this.fillColor = fillColor;
		this.frameTimer = startFrame;
		this.phase1 = 30;
		this.phase2 = this.phase1 + 5;
		this.phase3 = this.phase2 + 60;
		this.phase4 = this.phase3 + 5;
		this.phase5 = this.phase4 + 30;
		this.phase6 = this.phase5 + 30;

		this.lineExtendProgress = 0;
		this.firstPauseProgress = 0;
		this.arcSweepProgress = 0;
		this.secondPauseProgress = 0;
		this.lineRetractProgress = 0;
		this.circleExpandProgress = 0;
		this.strokeColor = this.fillColor;

		this.lineLength = 0;
		this.rotationAngle = 0;
		this.sweepAngle = 0;
		this.circleDiameter = 0;
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.rotationAngle);

		stroke(this.strokeColor);
		strokeWeight(this.diameter * 0.05);
		line(this.lineLength * cos(this.sweepAngle), this.lineLength * sin(this.sweepAngle), 0, 0);
		strokeWeight(this.diameter * 0.1);
		point(this.lineLength * cos(this.sweepAngle), this.lineLength * sin(this.sweepAngle));
		point(0, 0);

		noStroke();
		fill(this.fillColor);
		circle(0, 0, this.circleDiameter);

		stroke(this.strokeColor);
		strokeWeight(this.strokeThickness);
		noFill();
		arc(0, 0, this.diameter, this.diameter, 0, this.sweepAngle);

		pop();
	}

	update() {
		this.frameTimer++;
		this.lineExtendProgress = this.getPhaseProgress(0, this.phase1);
		this.firstPauseProgress = this.getPhaseProgress(this.phase1, this.phase2);
		this.arcSweepProgress = this.getPhaseProgress(this.phase2, this.phase3);
		this.secondPauseProgress = this.getPhaseProgress(this.phase3, this.phase4);
		this.lineRetractProgress = this.getPhaseProgress(this.phase4, this.phase5);
		this.circleExpandProgress = this.getPhaseProgress(this.phase5, this.phase6);
		if (this.lineExtendProgress !== null) {
			this.lineLength = lerp(0, this.diameter / 2, easeInOutQuad(this.lineExtendProgress));
		} else if (this.arcSweepProgress !== null) {
			this.sweepAngle = lerp(0, TAU, easeInOutQuad(this.arcSweepProgress));
		} else if (this.lineRetractProgress !== null) {
			this.lineLength = lerp(this.diameter / 2, 0, easeInOutQuad(this.lineRetractProgress));
		} else if (this.circleExpandProgress !== null) {
			this.circleDiameter = lerp(0, this.diameter, easeInOutQuad(this.circleExpandProgress));
		}
	}

	getPhaseProgress(start, end) {
		if (!(start < this.frameTimer && this.frameTimer < end)) return null;
		let progress = norm(this.frameTimer, start, end - 1);
		return progress;
	}

	run() {
		if (this.frameTimer > 0) this.display();
		this.update();
	}
}

/*------------------------------------------------------------------------------------------*/

class Zoom {
	constructor() {
		this.frameTimer = 0;
		this.duration = 40;
		this.scaleFactor = 1;
		this.targetScale = 20;
	}

	run() {
		this.frameTimer++;
		let progress = norm(this.frameTimer, 0, this.duration - 1);
		if (this.frameTimer < this.duration) {
			this.scaleFactor = lerp(1, this.targetScale, easeInOutQuad(progress));
		}
		translate(width / 2, height / 2);
		scale(this.scaleFactor);
		translate(-width / 2, -height / 2);
	}
}

